TOC.FLDID11, TOC.FLDTAG11, TOC.FLDTAGA11, GENHTAB_11.FLDTAB AS FLDTAB11, GENHTAB_11.FLDCOM AS FLDCOM11, GENHTAB_11.FLDCOMA AS FLDCOMA11, GENHTAB_11.FLDDFORMAT AS FLDDFORMAT11, GENHTAB_11.FLDIFORMAT AS FLDIFORMAT11, GENHTAB_11.FLDTYPE AS FLDTYPE11, GENHTAB_11.SUBLINKF AS SUBLINKF11,  GENHTAB_11.FLDSEARCH AS FLDSEARCH11, GENHTAB_11.FLDCRITERIA AS FLDCRITERIA11, GENHTAB_11.FLDCHGINF as FLDCHGINF11, GENHTAB_11.FLDLOWER as FLDLOWER11, GENHTAB_11.FLDUPPER as FLDUPPER11, GENHTAB_11.FLDREGEX as FLDREGEX11, GENHTAB_11.FLDMAP as FLDMAP11, CASE WHEN GENHTAB_11.FLDID1<>'' Then Cast(1 as Bit) else Cast(0 as Bit) end as SpreadInfoF11,
