CREATE PROCEDURE QCOBEXT_GENHTAB (@P_COB AS VARCHAR(10))
AS
SELECT  TOP 1
 COB.COB,
 COB.FLDID1, COB.FLDTAG1, GENHTAB_1.FLDTAB AS FLDTAB1, GENHTAB_1.FLDCOM AS FLDCOM1, GENHTAB_1.FLDDFORMAT AS FLDDFORMAT1, GENHTAB_1.FLDIFORMAT AS FLDIFORMAT1, GENHTAB_1.FLDTYPE AS FLDTYPE1, GENHTAB_1.SUBLINKF AS SUBLINKF1,  GENHTAB_1.FLDSEARCH AS FLDSEARCH1, GENHTAB_1.FLDCRITERIA AS FLDCRITERIA1,GENHTAB_1.FLDENCRYPTF AS FLDENCRYPTF1, CASE WHEN GENHTAB_1.FLDID1<>'' Then Cast(1 as Bit) else Cast(0 as Bit) end as SpreadInfoF1, 
