From
 COBEXT COB
 LEFT OUTER JOIN GENHTAB as GENHTAB_1 ON COB.FLDID1 = GENHTAB_1.FLDID
 LEFT OUTER JOIN GENHTAB as GENHTAB_2 ON COB.FLDID2 = GENHTAB_2.FLDID
 LEFT OUTER JOIN GENHTAB as GENHTAB_3 ON COB.FLDID3 = GENHTAB_3.FLDID
 LEFT OUTER JOIN GENHTAB as GENHTAB_4 ON COB.FLDID4 = GENHTAB_4.FLDID
 LEFT OUTER JOIN GENHTAB as GENHTAB_5 ON COB.FLDID5 = GENHTAB_5.FLDID
 LEFT OUTER JOIN GENHTAB as GENHTAB_6 ON COB.FLDID6 = GENHTAB_6.FLDID
 LEFT OUTER JOIN GENHTAB as GENHTAB_7 ON COB.FLDID7 = GENHTAB_7.FLDID
 LEFT OUTER JOIN GENHTAB as GENHTAB_8 ON COB.FLDID8 = GENHTAB_8.FLDID
 LEFT OUTER JOIN GENHTAB as GENHTAB_9 ON COB.FLDID9 = GENHTAB_9.FLDID
 LEFT OUTER JOIN GENHTAB as GENHTAB_10 ON COB.FLDID10 = GENHTAB_10.FLDID
 LEFT OUTER JOIN GENHTAB as GENHTAB_11 ON COB.FLDID11 = GENHTAB_11.FLDID
 LEFT OUTER JOIN GENHTAB as GENHTAB_12 ON COB.FLDID12 = GENHTAB_12.FLDID
 LEFT OUTER JOIN GENHTAB as GENHTAB_13 ON COB.FLDID13 = GENHTAB_13.FLDID
 LEFT OUTER JOIN GENHTAB as GENHTAB_14 ON COB.FLDID14 = GENHTAB_14.FLDID
 LEFT OUTER JOIN GENHTAB as GENHTAB_15 ON COB.FLDID15 = GENHTAB_15.FLDID
WHERE  COB.COB = @P_COB

GO

DROP PROCEDURE QTOI_GENHTAB 
GO
CREATE PROCEDURE QTOI_GENHTAB (@P_TOI AS VARCHAR(10), @P_NOC as VARCHAR(10)='')      
AS      
SELECT  TOP 1      
 TOI.TOI, TOI.DESCRIPTION,  
 TOI_EXT.FLDID1, TOI_EXT.FLDTAG1, GENHTAB_1.FLDTAB AS FLDTAB1, GENHTAB_1.FLDCOM AS FLDCOM1, GENHTAB_1.FLDDFORMAT AS FLDDFORMAT1, GENHTAB_1.FLDIFORMAT AS FLDIFORMAT1, GENHTAB_1.FLDTYPE AS FLDTYPE1, GENHTAB_1.SUBLINKF AS SUBLINKF1,  GENHTAB_1.FLDSEARCH AS FLDSEARCH1, GENHTAB_1.FLDCRITERIA AS FLDCRITERIA1, GENHTAB_1.FLDVALUATION AS FLDVALUATION1, CASE WHEN GENHTAB_1.FLDID1<>'' Then Cast(1 as Bit) else Cast(0 as Bit) end as SpreadInfoF1,
 TOI_EXT.FLDID2, TOI_EXT.FLDTAG2, GENHTAB_2.FLDTAB AS FLDTAB2, GENHTAB_2.FLDCOM AS FLDCOM2, GENHTAB_2.FLDDFORMAT AS FLDDFORMAT2, GENHTAB_2.FLDIFORMAT AS FLDIFORMAT2, GENHTAB_2.FLDTYPE AS FLDTYPE2, GENHTAB_2.SUBLINKF AS SUBLINKF2,  GENHTAB_2.FLDSEARCH AS FLDSEARCH2, GENHTAB_2.FLDCRITERIA AS FLDCRITERIA2, GENHTAB_2.FLDVALUATION AS FLDVALUATION2, CASE WHEN GENHTAB_2.FLDID1<>'' Then Cast(1 as Bit) else Cast(0 as Bit) end as SpreadInfoF2,    
 TOI_EXT.FLDID3, TOI_EXT.FLDTAG3, GENHTAB_3.FLDTAB AS FLDTAB3, GENHTAB_3.FLDCOM AS FLDCOM3, GENHTAB_3.FLDDFORMAT AS FLDDFORMAT3, GENHTAB_3.FLDIFORMAT AS FLDIFORMAT3, GENHTAB_3.FLDTYPE AS FLDTYPE3, GENHTAB_3.SUBLINKF AS SUBLINKF3,  GENHTAB_3.FLDSEARCH AS FLDSEARCH3, GENHTAB_3.FLDCRITERIA AS FLDCRITERIA3, GENHTAB_3.FLDVALUATION AS FLDVALUATION3, CASE WHEN GENHTAB_3.FLDID1<>'' Then Cast(1 as Bit) else Cast(0 as Bit) end as SpreadInfoF3,
 TOI_EXT.FLDID4, TOI_EXT.FLDTAG4, GENHTAB_4.FLDTAB AS FLDTAB4, GENHTAB_4.FLDCOM AS FLDCOM4, GENHTAB_4.FLDDFORMAT AS FLDDFORMAT4, GENHTAB_4.FLDIFORMAT AS FLDIFORMAT4, GENHTAB_4.FLDTYPE AS FLDTYPE4, GENHTAB_4.SUBLINKF AS SUBLINKF4,  GENHTAB_4.FLDSEARCH AS FLDSEARCH4, GENHTAB_4.FLDCRITERIA AS FLDCRITERIA4, GENHTAB_4.FLDVALUATION AS FLDVALUATION4, CASE WHEN GENHTAB_4.FLDID1<>'' Then Cast(1 as Bit) else Cast(0 as Bit) end as SpreadInfoF4,    
 TOI_EXT.FLDID5, TOI_EXT.FLDTAG5, GENHTAB_5.FLDTAB AS FLDTAB5, GENHTAB_5.FLDCOM AS FLDCOM5, GENHTAB_5.FLDDFORMAT AS FLDDFORMAT5, GENHTAB_5.FLDIFORMAT AS FLDIFORMAT5, GENHTAB_5.FLDTYPE AS FLDTYPE5, GENHTAB_5.SUBLINKF AS SUBLINKF5,  GENHTAB_5.FLDSEARCH AS FLDSEARCH5, GENHTAB_5.FLDCRITERIA AS FLDCRITERIA5, GENHTAB_5.FLDVALUATION AS FLDVALUATION5, CASE WHEN GENHTAB_5.FLDID1<>'' Then Cast(1 as Bit) else Cast(0 as Bit) end as SpreadInfoF5,    
 TOI_EXT.FLDID6, TOI_EXT.FLDTAG6, GENHTAB_6.FLDTAB AS FLDTAB6, GENHTAB_6.FLDCOM AS FLDCOM6, GENHTAB_6.FLDDFORMAT AS FLDDFORMAT6, GENHTAB_6.FLDIFORMAT AS FLDIFORMAT6, GENHTAB_6.FLDTYPE AS FLDTYPE6, GENHTAB_6.SUBLINKF AS SUBLINKF6,  GENHTAB_6.FLDSEARCH AS FLDSEARCH6, GENHTAB_6.FLDCRITERIA AS FLDCRITERIA6, GENHTAB_6.FLDVALUATION AS FLDVALUATION6, CASE WHEN GENHTAB_6.FLDID1<>'' Then Cast(1 as Bit) else Cast(0 as Bit) end as SpreadInfoF6,    
 TOI_EXT.FLDID7, TOI_EXT.FLDTAG7, GENHTAB_7.FLDTAB AS FLDTAB7, GENHTAB_7.FLDCOM AS FLDCOM7, GENHTAB_7.FLDDFORMAT AS FLDDFORMAT7, GENHTAB_7.FLDIFORMAT AS FLDIFORMAT7, GENHTAB_7.FLDTYPE AS FLDTYPE7, GENHTAB_7.SUBLINKF AS SUBLINKF7,  GENHTAB_7.FLDSEARCH AS FLDSEARCH7, GENHTAB_7.FLDCRITERIA AS FLDCRITERIA7, GENHTAB_7.FLDVALUATION AS FLDVALUATION7, CASE WHEN GENHTAB_7.FLDID1<>'' Then Cast(1 as Bit) else Cast(0 as Bit) end as SpreadInfoF7,
 TOI_EXT.FLDID8, TOI_EXT.FLDTAG8, GENHTAB_8.FLDTAB AS FLDTAB8, GENHTAB_8.FLDCOM AS FLDCOM8, GENHTAB_8.FLDDFORMAT AS FLDDFORMAT8, GENHTAB_8.FLDIFORMAT AS FLDIFORMAT8, GENHTAB_8.FLDTYPE AS FLDTYPE8, GENHTAB_8.SUBLINKF AS SUBLINKF8,  GENHTAB_8.FLDSEARCH AS FLDSEARCH8, GENHTAB_8.FLDCRITERIA AS FLDCRITERIA8, GENHTAB_8.FLDVALUATION AS FLDVALUATION8, CASE WHEN GENHTAB_8.FLDID1<>'' Then Cast(1 as Bit) else Cast(0 as Bit) end as SpreadInfoF8,    
 TOI_EXT.FLDID9, TOI_EXT.FLDTAG9, GENHTAB_9.FLDTAB AS FLDTAB9, GENHTAB_9.FLDCOM AS FLDCOM9, GENHTAB_9.FLDDFORMAT AS FLDDFORMAT9, GENHTAB_9.FLDIFORMAT AS FLDIFORMAT9, GENHTAB_9.FLDTYPE AS FLDTYPE9, GENHTAB_9.SUBLINKF AS SUBLINKF9,  GENHTAB_9.FLDSEARCH AS FLDSEARCH9, GENHTAB_9.FLDCRITERIA AS FLDCRITERIA9, GENHTAB_9.FLDVALUATION AS FLDVALUATION9, CASE WHEN GENHTAB_9.FLDID1<>'' Then Cast(1 as Bit) else Cast(0 as Bit) end as SpreadInfoF9,    
 TOI_EXT.FLDID10, TOI_EXT.FLDTAG10, GENHTAB_10.FLDTAB AS FLDTAB10, GENHTAB_10.FLDCOM AS FLDCOM10, GENHTAB_10.FLDDFORMAT AS FLDDFORMAT10, GENHTAB_10.FLDIFORMAT AS FLDIFORMAT10, GENHTAB_10.FLDTYPE AS FLDTYPE10, GENHTAB_10.SUBLINKF AS SUBLINKF10,  GENHTAB_10.FLDSEARCH AS FLDSEARCH10, GENHTAB_10.FLDCRITERIA AS FLDCRITERIA10, GENHTAB_10.FLDVALUATION AS FLDVALUATION10, CASE WHEN GENHTAB_10.FLDID1<>'' Then Cast(1 as Bit) else Cast(0 as Bit) end as SpreadInfoF10,     
 TOI_EXT.FLDID11, TOI_EXT.FLDTAG11, GENHTAB_11.FLDTAB AS FLDTAB11, GENHTAB_11.FLDCOM AS FLDCOM11, GENHTAB_11.FLDDFORMAT AS FLDDFORMAT11, GENHTAB_11.FLDIFORMAT AS FLDIFORMAT11, GENHTAB_11.FLDTYPE AS FLDTYPE11, GENHTAB_11.SUBLINKF AS SUBLINKF11,  GENHTAB_11.FLDSEARCH AS FLDSEARCH11, GENHTAB_11.FLDCRITERIA AS FLDCRITERIA11, GENHTAB_11.FLDVALUATION AS FLDVALUATION11, CASE WHEN GENHTAB_11.FLDID1<>'' Then Cast(1 as Bit) else Cast(0 as Bit) end as SpreadInfoF11,    
 TOI_EXT.FLDID12, TOI_EXT.FLDTAG12, GENHTAB_12.FLDTAB AS FLDTAB12, GENHTAB_12.FLDCOM AS FLDCOM12, GENHTAB_12.FLDDFORMAT AS FLDDFORMAT12, GENHTAB_12.FLDIFORMAT AS FLDIFORMAT12, GENHTAB_12.FLDTYPE AS FLDTYPE12, GENHTAB_12.SUBLINKF AS SUBLINKF12,  GENHTAB_12.FLDSEARCH AS FLDSEARCH12, GENHTAB_12.FLDCRITERIA AS FLDCRITERIA12, GENHTAB_12.FLDVALUATION AS FLDVALUATION12, CASE WHEN GENHTAB_12.FLDID1<>'' Then Cast(1 as Bit) else Cast(0 as Bit) end as SpreadInfoF12,    
 TOI_EXT.FLDID13, TOI_EXT.FLDTAG13, GENHTAB_13.FLDTAB AS FLDTAB13, GENHTAB_13.FLDCOM AS FLDCOM13, GENHTAB_13.FLDDFORMAT AS FLDDFORMAT13, GENHTAB_13.FLDIFORMAT AS FLDIFORMAT13, GENHTAB_13.FLDTYPE AS FLDTYPE13, GENHTAB_13.SUBLINKF AS SUBLINKF13,  GENHTAB_13.FLDSEARCH AS FLDSEARCH13, GENHTAB_13.FLDCRITERIA AS FLDCRITERIA13, GENHTAB_13.FLDVALUATION AS FLDVALUATION13, CASE WHEN GENHTAB_13.FLDID1<>'' Then Cast(1 as Bit) else Cast(0 as Bit) end as SpreadInfoF13,    
 TOI_EXT.FLDID14, TOI_EXT.FLDTAG14, GENHTAB_14.FLDTAB AS FLDTAB14, GENHTAB_14.FLDCOM AS FLDCOM14, GENHTAB_14.FLDDFORMAT AS FLDDFORMAT14, GENHTAB_14.FLDIFORMAT AS FLDIFORMAT14, GENHTAB_14.FLDTYPE AS FLDTYPE14, GENHTAB_14.SUBLINKF AS SUBLINKF14,  GENHTAB_14.FLDSEARCH AS FLDSEARCH14, GENHTAB_14.FLDCRITERIA AS FLDCRITERIA14, GENHTAB_14.FLDVALUATION AS FLDVALUATION14, CASE WHEN GENHTAB_14.FLDID1<>'' Then Cast(1 as Bit) else Cast(0 as Bit) end as SpreadInfoF14,    
 TOI_EXT.FLDID15, TOI_EXT.FLDTAG15, GENHTAB_15.FLDTAB AS FLDTAB15, GENHTAB_15.FLDCOM AS FLDCOM15, GENHTAB_15.FLDDFORMAT AS FLDDFORMAT15, GENHTAB_15.FLDIFORMAT AS FLDIFORMAT15, GENHTAB_15.FLDTYPE AS FLDTYPE15, GENHTAB_15.SUBLINKF AS SUBLINKF15,  GENHTAB_15.FLDSEARCH AS FLDSEARCH15, GENHTAB_15.FLDCRITERIA AS FLDCRITERIA15, GENHTAB_15.FLDVALUATION AS FLDVALUATION15, CASE WHEN GENHTAB_15.FLDID1<>'' Then Cast(1 as Bit) else Cast(0 as Bit) end as SpreadInfoF15
FROM               
 TOI
 LEFT JOIN TOI_EXT on (TOI_EXT.TOI=TOI.TOI AND TOI_EXT.NOC = @P_NOC)
 LEFT OUTER JOIN GENHTAB as GENHTAB_1 ON TOI_EXT.FLDID1 = GENHTAB_1.FLDID      
 LEFT OUTER JOIN GENHTAB as GENHTAB_2 ON TOI_EXT.FLDID2 = GENHTAB_2.FLDID      
 LEFT OUTER JOIN GENHTAB as GENHTAB_3 ON TOI_EXT.FLDID3 = GENHTAB_3.FLDID      
 LEFT OUTER JOIN GENHTAB as GENHTAB_4 ON TOI_EXT.FLDID4 = GENHTAB_4.FLDID      
 LEFT OUTER JOIN GENHTAB as GENHTAB_5 ON TOI_EXT.FLDID5 = GENHTAB_5.FLDID      
 LEFT OUTER JOIN GENHTAB as GENHTAB_6 ON TOI_EXT.FLDID6 = GENHTAB_6.FLDID      
 LEFT OUTER JOIN GENHTAB as GENHTAB_7 ON TOI_EXT.FLDID7 = GENHTAB_7.FLDID      
 LEFT OUTER JOIN GENHTAB as GENHTAB_8 ON TOI_EXT.FLDID8 = GENHTAB_8.FLDID      
 LEFT OUTER JOIN GENHTAB as GENHTAB_9 ON TOI_EXT.FLDID9 = GENHTAB_9.FLDID      
 LEFT OUTER JOIN GENHTAB as GENHTAB_10 ON TOI_EXT.FLDID10 = GENHTAB_10.FLDID      
 LEFT OUTER JOIN GENHTAB as GENHTAB_11 ON TOI_EXT.FLDID11 = GENHTAB_11.FLDID      
